?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Traffic Router - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/router.css"><style>
.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub{color:#66758d;margin-top:5px}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.btn.primary{background:#087cff;color:#fff;border-color:#087cff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-bottom:18px}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;padding:20px}.label{font-size:12px;color:#66758d}.value{font-size:27px;font-weight:700;margin-top:7px}.meta{font-size:12px;color:#718096;margin-top:5px}.bar{height:12px;background:#edf2f7;border-radius:99px;overflow:hidden;margin-top:14px}.bar i{display:block;height:100%;width:0;border-radius:99px}.rx{background:#087cff}.tx{background:#12a36a}.card h3{margin:0 0 16px;font-size:16px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px;border-bottom:1px solid #edf1f6;text-align:left;font-size:13px}.table th{font-size:11px;color:#61718a;text-transform:uppercase;background:#f7f9fc}.num{text-align:right!important;font-variant-numeric:tabular-nums}.status{display:inline-block;padding:5px 9px;border-radius:99px;font-size:11px;font-weight:700}.up{background:#dff6e9;color:#08774e}.down{background:#fde5e5;color:#b42318}.notice{color:#66758d;padding:18px}.foot{margin-top:12px;color:#718096;font-size:12px}@media(max-width:800px){.page{margin-left:0;padding:20px}.grid{grid-template-columns:1fr}.head{align-items:flex-start;gap:12px;flex-direction:column}}
</style></head><body><main class="page"><div class="head"><div><div class="title">Traffic Router</div><div class="sub">Monitoring RX/TX interface MikroTik secara realtime.</div></div><button class="btn primary" id="refresh">↻ Refresh</button></div><div class="grid"><div class="card"><div class="label">Total RX</div><div class="value" id="totalRx">0 B</div><div class="meta">Akumulasi byte diterima seluruh interface</div></div><div class="card"><div class="label">Total TX</div><div class="value" id="totalTx">0 B</div><div class="meta">Akumulasi byte dikirim seluruh interface</div></div></div><div class="card"><h3>Interface Traffic</h3><div style="overflow:auto"><table class="table"><thead><tr><th>Interface</th><th>Status</th><th class="num">RX</th><th class="num">TX</th></tr></thead><tbody id="rows"><tr><td colspan="4" class="notice">Memuat data...</td></tr></tbody></table></div><div class="foot" id="updated">Belum diperbarui</div></div></main><script>
const rows=document.getElementById('rows'),refresh=document.getElementById('refresh'),totalRx=document.getElementById('totalRx'),totalTx=document.getElementById('totalTx'),updated=document.getElementById('updated');const fmt=n=>{n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'};const esc=v=>String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function load(){refresh.disabled=true;try{const r=await fetch('../api/router_interfaces.php?nocache='+Date.now(),{cache:'no-store'});const d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');let rx=0,tx=0;rows.innerHTML=(d.interfaces||[]).map(x=>{rx+=Number(x.rx_bytes)||0;tx+=Number(x.tx_bytes)||0;return `<tr><td><strong>${esc(x.name)}</strong></td><td><span class="status ${x.running&&!x.disabled?'up':'down'}">${x.disabled?'DISABLED':x.running?'RUNNING':'DOWN'}</span></td><td class="num">${fmt(x.rx_bytes)}</td><td class="num">${fmt(x.tx_bytes)}</td></tr>`}).join('')||'<tr><td colspan="4" class="notice">Tidak ada interface.</td></tr>';totalRx.textContent=fmt(rx);totalTx.textContent=fmt(tx);updated.textContent='Update '+new Date().toLocaleTimeString('id-ID')}catch(e){rows.innerHTML='<tr><td colspan="4" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>'}finally{refresh.disabled=false}}refresh.addEventListener('click',load);load();setInterval(load,5000);
</script><script src="../assets/js/app.js?v=6"></script></body></html>